create extension if not exists citext;
create extension if not exists pgcrypto;
create type public.risk_class as enum ('low','medium','high','critical');
create type public.run_status as enum ('queued','running','succeeded','failed','cancelled');
create type public.approval_decision as enum ('pending','approved','rejected','expired');
create table public.app_users (id uuid primary key references auth.users(id) on delete cascade, email citext unique not null check (lower(email) = 'matthewirving99@gmail.com'), display_name text, timezone text not null default 'Europe/London', is_allowed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.personal_profiles (user_id uuid primary key references public.app_users(id) on delete cascade, planning_preferences jsonb not null default '{}'::jsonb, notification_preferences jsonb not null default '{}'::jsonb, privacy_preferences jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.managers (id uuid primary key default gen_random_uuid(), code text unique not null check (code in ('finance','career','personal','health','systems','digital_estate','travel','procurement')), name text not null, description text not null, enabled boolean not null default false, configuration jsonb not null default '{}'::jsonb, risk_class public.risk_class not null default 'medium', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workflow_definitions (id uuid primary key default gen_random_uuid(), manager_id uuid not null references public.managers(id), code text unique not null, version integer not null check (version > 0), trigger_type text not null, input_schema jsonb not null default '{}'::jsonb, output_schema jsonb not null default '{}'::jsonb, active boolean not null default false, created_at timestamptz not null default now(), unique(manager_id, version));
create table public.workflow_schedules (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), workflow_definition_id uuid not null references public.workflow_definitions(id), cron_expression text not null, timezone text not null default 'Europe/London', next_due_at timestamptz, enabled boolean not null default false, created_at timestamptz not null default now());
create table public.workflow_runs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), workflow_definition_id uuid not null references public.workflow_definitions(id), status public.run_status not null default 'queued', trigger text not null, correlation_id uuid not null default gen_random_uuid(), idempotency_key text unique not null, requested_at timestamptz not null default now(), started_at timestamptz, completed_at timestamptz, error_code text, redacted_error text);
create table public.actions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), run_id uuid references public.workflow_runs(id), action_type text not null, title text not null, description text not null, risk_class public.risk_class not null, status text not null default 'proposed', proposed_payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.approvals (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), action_id uuid references public.actions(id), decision public.approval_decision not null default 'pending', required_aal text not null default 'aal2', payload_hash text not null, expires_at timestamptz not null, decided_at timestamptz);
create table public.reports (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), run_id uuid references public.workflow_runs(id), report_type text not null, title text not null, summary text not null, markdown text not null, structured_metrics jsonb not null default '{}'::jsonb, status text not null default 'draft', created_at timestamptz not null default now());
create table public.monthly_budgets (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), month date not null, recurring_target numeric(12,2) not null default 5.00 check(recurring_target >= 0), recurring_hard_cap numeric(12,2) not null default 10.00 check(recurring_hard_cap >= recurring_target), currency char(3) not null default 'USD', actual_recurring numeric(12,2) not null default 0, actual_on_demand numeric(12,2) not null default 0, unique(user_id,month));
create table public.audit_events (id uuid primary key default gen_random_uuid(), user_id uuid references public.app_users(id), actor_type text not null, action_type text not null, target_type text not null, target_id text, aal text, correlation_id uuid, redacted_before jsonb, redacted_after jsonb, result text not null, created_at timestamptz not null default now());
create table public.trace_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), correlation_id uuid not null, event_type text not null, severity text not null default 'info', redacted_payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.connections (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), provider text not null, account_label text not null, status text not null default 'disconnected', encrypted_credential_reference text, scopes text[] not null default '{}', created_at timestamptz not null default now());
create table public.source_objects (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), r2_key text unique not null, sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'), size_bytes bigint not null check(size_bytes >= 0), mime_type text not null, data_classification text not null, source text not null, captured_at timestamptz not null, created_at timestamptz not null default now());
create table public.data_freshness (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.app_users(id), source text not null, last_source_at timestamptz, last_success_at timestamptz, expected_cadence interval, state text not null, unique(user_id, source));
create index workflow_runs_user_requested_idx on public.workflow_runs(user_id, requested_at desc); create index trace_events_correlation_idx on public.trace_events(correlation_id, created_at); create index audit_events_user_created_idx on public.audit_events(user_id, created_at desc);
alter table public.app_users enable row level security; alter table public.personal_profiles enable row level security; alter table public.managers enable row level security; alter table public.workflow_definitions enable row level security; alter table public.workflow_schedules enable row level security; alter table public.workflow_runs enable row level security; alter table public.actions enable row level security; alter table public.approvals enable row level security; alter table public.reports enable row level security; alter table public.monthly_budgets enable row level security; alter table public.audit_events enable row level security; alter table public.trace_events enable row level security; alter table public.connections enable row level security; alter table public.source_objects enable row level security; alter table public.data_freshness enable row level security;
create policy own_app_users on public.app_users for select using (id = auth.uid() and is_allowed); create policy own_profiles on public.personal_profiles using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_schedules on public.workflow_schedules using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_runs on public.workflow_runs for select using(user_id=auth.uid()); create policy own_actions on public.actions using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_approvals on public.approvals using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_reports on public.reports for select using(user_id=auth.uid()); create policy own_budgets on public.monthly_budgets using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_audit on public.audit_events for select using(user_id=auth.uid()); create policy own_traces on public.trace_events for select using(user_id=auth.uid()); create policy own_connections on public.connections using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_objects on public.source_objects using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy own_freshness on public.data_freshness using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into public.managers(code,name,description,risk_class) values ('finance','Finance Operations','Financial close and analysis','high'),('career','Career Operations','Career evidence and planning','medium'),('personal','Personal Operations','Personal planning','medium'),('health','Health & Performance','Non-diagnostic health analysis','high'),('systems','Systems & Automation','Platform operations','high'),('digital_estate','Digital Estate','Device and file safety','critical'),('travel','Travel Planning','Research and planning','medium'),('procurement','Consumer & Procurement','Research and recommendations','medium');
